// fayl: next.config.ts
import type { NextConfig } from "next"
import { readFile } from "node:fs/promises"

type Move = { from: string; to: string }

export default async function config(): Promise<NextConfig> {
  const moves: Move[] = JSON.parse(await readFile("./data/moves.json", "utf8"))

  return {
    async redirects() {
      return moves.map((m) => ({ source: m.from, destination: m.to, permanent: true }))
    },
  }
}

