import { readFile } from "node:fs/promises"
import path from "node:path"

export async function GET(request: Request) {
  const name = new URL(request.url).searchParams.get("font") ?? "Inter"
  const font = await readFile(path.join(process.cwd(), "fonts", `${name}.ttf`))
  return Response.json({ font: name, bytes: font.byteLength })
}

