import { describe, expect, it } from "vitest"
import { getRedirectUrl, unstable_getResponseFromNextConfig } from "next/experimental/testing/server"
import nextConfig from "./next.config"

describe("next.config", () => {
  it("/taomlar → /menu", async () => {
    const res = await unstable_getResponseFromNextConfig({ url: "https://oshxona.uz/taomlar", nextConfig })
    expect(res.status).toBe(308)
    expect(getRedirectUrl(res)).toBe("https://oshxona.uz/menu")
  })

  it("xavfsizlik sarlavhasi", async () => {
    const res = await unstable_getResponseFromNextConfig({ url: "https://oshxona.uz/", nextConfig })
    expect(res.headers.get("x-content-type-options")).toBe("nosniff")
  })
})

// fayl: next.config.ts
import type { NextConfig } from "next"
import { PHASE_DEVELOPMENT_SERVER } from "next/constants"

const securityHeaders = [
  { key: "Strict-Transport-Security", value: "max-age=63072000; includeSubDomains; preload" },
  { key: "X-Content-Type-Options", value: "nosniff" },
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  { key: "Permissions-Policy", value: "camera=(), microphone=(), geolocation=()" },
]

export default function config(phase: string): NextConfig {
  const isDev = phase === PHASE_DEVELOPMENT_SERVER

  return {
    output: "standalone", // Docker image uchun
    poweredByHeader: false,
    reactCompiler: true,
    cacheComponents: true,
    partialPrefetching: true,
    typedRoutes: true,
    deploymentId: process.env.GIT_COMMIT_SHA,
    assetPrefix: isDev ? undefined : process.env.CDN_URL,
    images: {
      formats: ["image/avif", "image/webp"],
      remotePatterns: [new URL("https://cdn.oshxona.uz/uploads/**")],
    },
    cacheLife: {
      menu: { stale: 300, revalidate: 900, expire: 86400 },
    },
    logging: isDev ? { fetches: { fullUrl: true } } : undefined,
    async headers() {
      return [{ source: "/:path*", headers: securityHeaders }]
    },
    async redirects() {
      return [{ source: "/taomlar/:slug", destination: "/menu/:slug", permanent: true }]
    },
  }
}

