type PublicConfig = { apiUrl: string; appEnv: string }

export function ConfigStatus() {
  const [config, setConfig] = useState<PublicConfig | null>(null)
  useEffect(() => {
    fetch("/api/public-config")
      .then((r) => r.json())
      .then(setConfig)
  }, [])
  if (!config) return <p>Sozlamalar yuklanmoqda...</p>
