WEBHOOK_SECRET_PREVIOUS=eski-kalit-2025   # o'tish davri tugagach o'chiriladi

// fayl: app/api/webhooks/payment/route.ts
import { createHmac, timingSafeEqual } from "node:crypto"

function sign(body: string, secret: string) {
  return createHmac("sha256", secret).update(body).digest("hex")
}

function verify(body: string, signature: string) {
  const secrets = [process.env.WEBHOOK_SECRET, process.env.WEBHOOK_SECRET_PREVIOUS].filter(
    (s): s is string => Boolean(s),
  )
  return secrets.some((secret) => {
    const expected = Buffer.from(sign(body, secret))
    const given = Buffer.from(signature)
    return expected.length === given.length && timingSafeEqual(expected, given)
  })
}

export async function POST(request: Request) {
  const body = await request.text()
  if (!verify(body, request.headers.get("x-signature") ?? "")) {
    return Response.json({ error: "imzo noto'g'ri" }, { status: 401 })
  }
  return Response.json({ received: true })
}

