// fayl: app/blog/[slug]/page.tsx
import { notFound } from "next/navigation"
import type { ComponentType } from "react"

const posts = import.meta.glob("/content/posts/*.tsx", { import: "default" })

export default async function PostPage(props: PageProps<"/blog/[slug]">) {
  const { slug } = await props.params
  const load = posts[`/content/posts/${slug}.tsx`]
  if (!load) notFound()

  const Post = (await load()) as ComponentType
  return (
    <article>
      <Post />
    </article>
  )
}

