// fayl: app/cart-total.tsx
"use client"

export function CartTotal({ items }: { items: { price: number; qty: number }[] }) {
  // useMemo yozilmagan — kompilyator o'zi memo qiladi
  const total = items.reduce((sum, i) => sum + i.price * i.qty, 0)
  return <p>Jami: {total} so'm</p>
}

