// fayl: apps/web/next.config.ts
import path from "node:path"
import type { NextConfig } from "next"
import createMDX from "@next/mdx"

const root = path.join(__dirname, "../..")

const nextConfig: NextConfig = {
  output: "standalone",
  pageExtensions: ["ts", "tsx", "md", "mdx"],

  // Monorepo: ikkala ildiz bir xil
  outputFileTracingRoot: root,
  outputFileTracingIncludes: {
    "/api/recipes/*": ["./content/recipes/**/*.md"],
  },

  turbopack: {
    root,
    rules: {
      "*.svg": {
        condition: { not: "foreign" }, // node_modules'dagi SVG'larga tegmaymiz
        loaders: ["@svgr/webpack"],
        as: "*.js",
      },
      "*.sql": { type: "raw" },
    },
    resolveAlias: { "~*": "*" },
    ignoreIssue: [{ path: "**/lib/optional-feature/**", title: "Module not found" }],
    debugIds: true,
  },

  compiler: {
    define: { __APP_VERSION__: process.env.APP_VERSION ?? "dev" },
  },

  experimental: {
    // Toza Docker qatlamida yig'ilsa — keshni yozmaymiz
    turbopackFileSystemCacheForBuild: process.env.NEXT_BUILD_CACHE !== "off",
  },
}

const withMDX = createMDX({
  options: { remarkPlugins: ["remark-gfm"] },
})

export default withMDX(nextConfig)
